CURRENT_COUNT_INPUT_SHA256 = "be2747fe98bfd884fc7b48a3b90e8bf842d42f5abc8a6290cce20a70199b7666"
CURRENT_COUNTS = None
NATIVE_LAYER_COUNTS = None
CURRENT_REGISTRY_CONTEXT = None
