def current_count(name: str) -> Any:
    require(type(CURRENT_COUNTS) is dict and name in CURRENT_COUNTS, "actual_current_registry_must_be_loaded")
    return CURRENT_COUNTS[name]


def current_key_contract(value: Any, kind: str) -> None:
    if CURRENT_KEY_CONTRACT and kind in current_count("current_exact_keys"):
        keys = current_count("current_exact_keys")[kind]
        require(type(value) is dict and len(value) == current_count("key_counts")[kind] and set(value) == set(keys),
                "current_registered_exact_keys:" + kind)


def finish_current_count_registry() -> None:
    require(type(CURRENT_REGISTRY_CONTEXT) is dict and
            file_pin(CURRENT_REGISTRY_CONTEXT["path"]) == CURRENT_REGISTRY_CONTEXT["pin"],
            "current_registry_full_D3_preserved_after_use")
    finish_registered_public_metadata()


def current_final_parent_counts(value: Any) -> None:
    pairs = (("anchor_completed_steps", "upstream_completed_steps"),
        ("anchor_accepted_parent_batch_rows", "accepted_parent_batch_rows"),
        ("anchor_previous_parent_batch_rows", "previous_parent_batch_rows"),
        ("anchor_total_parent_batch_rows", "total_parent_batch_rows"))
    require(all(integer(value.get(key)) and value[key] == current_count(name) for key, name in pairs),
            "current_final_previous_and_total_parent_rows")


